CGImageRef TMSpotifyThumbnail(NSData *encoded,CGFloat maxPixel){if(!encoded.length||encoded.length>8*1024*1024)return NULL;CGImageSourceRef src=CGImageSourceCreateWithData((__bridge CFDataRef)encoded,NULL);if(!src)return NULL;NSDictionary *opts=@{(__bridge id)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(__bridge id)kCGImageSourceThumbnailMaxPixelSize:@((size_t)maxPixel),(__bridge id)kCGImageSourceCreateThumbnailWithTransform:@YES};CGImageRef img=CGImageSourceCreateThumbnailAtIndex(src,0,(__bridge CFDictionaryRef)opts);CFRelease(src);return img;}
NSData *TMGrayCover(CGImageRef image){if(!image)return nil;size_t w=CGImageGetWidth(image),h=CGImageGetHeight(image),side=MIN(w,h);if(!side)return nil;CGRect crop=CGRectMake((w-side)/2.0,(h-side)/2.0,side,side);CGImageRef square=CGImageCreateWithImageInRect(image,crop);if(!square)return nil;NSMutableData *d=[NSMutableData dataWithLength:TM_COVER_BYTES];CGColorSpaceRef cs=CGColorSpaceCreateDeviceGray();CGContextRef ctx=CGBitmapContextCreate(d.mutableBytes,144,144,8,144,cs,kCGImageAlphaNone);CGColorSpaceRelease(cs);if(!ctx){CGImageRelease(square);return nil;}CGContextSetInterpolationQuality(ctx,kCGInterpolationHigh);CGContextDrawImage(ctx,CGRectMake(0,0,144,144),square);CGContextRelease(ctx);CGImageRelease(square);return d;}
